use super::ffi::{self,SciFnDirect,Sptr};
use std::ffi::{CStr,CString};
#[derive(Debug)]pub struct DirectEditor{function:SciFnDirect,pointer:Sptr}
impl DirectEditor{/// Construct a direct-call wrapper from Scintilla's function and object pointers.
    ///
    /// # Safety
    /// The function pointer must be a valid `SciFnDirect` for the supplied Scintilla object pointer, and both pointers must remain valid for the lifetime of the wrapper.
    pub unsafe fn from_raw(f:Sptr,p:Sptr)->Option<Self>{if f==0||p==0{return None}Some(Self{function:unsafe{std::mem::transmute::<Sptr,SciFnDirect>(f)},pointer:p})}pub fn send(&self,msg:u32,w:usize,l:Sptr)->Sptr{unsafe{(self.function)(self.pointer,msg,w,l)}}pub fn set_text(&self,text:&str){let t=CString::new(text.replace('\0',"�")).expect("literal");self.send(ffi::SCI_SETTEXT,0,t.as_ptr()as Sptr);}pub fn get_text(&self)->String{let len=self.send(ffi::SCI_GETLENGTH,0,0).max(0)as usize;let mut buffer=vec![0u8;len.saturating_add(1)];let read=self.send(ffi::SCI_GETTEXT,buffer.len(),buffer.as_mut_ptr()as Sptr).max(0)as usize;buffer.truncate(read.min(buffer.len()));CStr::from_bytes_until_nul(&buffer).map_or_else(|_|String::from_utf8_lossy(&buffer).into_owned(),|s|s.to_string_lossy().into_owned())}pub fn set_colours(&self,foreground:(u8,u8,u8),background:(u8,u8,u8),caret:(u8,u8,u8)){let pack=|c:(u8,u8,u8)|->Sptr{(u32::from(c.0)|u32::from(c.1)<<8|u32::from(c.2)<<16) as Sptr};self.send(ffi::SCI_STYLESETFORE,0,pack(foreground));self.send(ffi::SCI_STYLESETBACK,0,pack(background));self.send(ffi::SCI_SETCARETFORE,0,pack(caret));self.send(ffi::SCI_SETMARGINWIDTHN,0,0);}pub fn replace_selection(&self,text:&str){let t=CString::new(text.replace('\0',"�")).expect("literal");self.send(ffi::SCI_REPLACESEL,0,t.as_ptr()as Sptr);}pub fn insert_text(&self,pos:usize,text:&str){let t=CString::new(text.replace('\0',"�")).expect("literal");self.send(ffi::SCI_INSERTTEXT,pos,t.as_ptr()as Sptr);}pub fn begin_undo_action(&self){self.send(ffi::SCI_BEGINUNDOACTION,0,0);}pub fn end_undo_action(&self){self.send(ffi::SCI_ENDUNDOACTION,0,0);}pub fn undo(&self){self.send(ffi::SCI_UNDO,0,0);}pub fn redo(&self){self.send(ffi::SCI_REDO,0,0);}pub fn line_start(&self,line:usize)->usize{self.send(ffi::SCI_POSITIONFROMLINE,line,0).max(0)as usize}pub fn line_length(&self,line:usize)->usize{self.send(ffi::SCI_LINELENGTH,line,0).max(0)as usize}pub fn configure_indicator(&self,slot:usize,colour:(u8,u8,u8),alpha:u8){let pack=|c:(u8,u8,u8)|->Sptr{(u32::from(c.0)|u32::from(c.1)<<8|u32::from(c.2)<<16) as Sptr};self.send(ffi::SCI_INDICSETSTYLE,slot,ffi::INDIC_FULLBOX as Sptr);self.send(ffi::SCI_INDICSETFORE,slot,pack(colour));self.send(ffi::SCI_INDICSETALPHA,slot,alpha as Sptr);}pub fn clear_indicator(&self,slot:usize,start:usize,len:usize){self.send(ffi::SCI_SETINDICATORCURRENT,slot,0);self.send(ffi::SCI_INDICATORCLEARRANGE,len,start as Sptr);}pub fn set_indicator_range(&self,slot:usize,start:usize,len:usize){self.send(ffi::SCI_SETINDICATORCURRENT,slot,0);self.send(ffi::SCI_INDICATORFILLRANGE,len,start as Sptr);}}
